const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state,tab='overview',lastTab='',member='',persona='gpt',memberQuery='',memQuery='',groupSel='';
try{const saved=sessionStorage.getItem('qqfriend.tab');if(saved)tab=saved;}catch{}
const memUi={status:'all',category:'all',editing:'',picked:new Set()};
// 表情包管理 loads its own list (images are not part of /api/state).
let media=null,mediaLoading=false,mediaQuery='';const mediaUi={filter:'repeat',picked:new Set()};
