if(!labels[tab])tab='overview';
const roleNames={tool_audit:'工具调用审核',reply_repair:'回复缩短',observer:'观察群聊',reply:'人格回复',memory:'记忆整理',auditor:'话题审核',discovery:'发现话题',perception:'媒体理解',preview:'回复预览'},role=r=>roleNames[r]||r;
const outboxStatus={queued:'排队中',sending:'发送中',sent:'已发送',cancelled:'已取消',unknown:'结果未知'},outboxCategory={reply:'接话',approval:'审批预览',proactive:'主动话题'};
const proposalStatus={auditing:'审核中',pending:'待你批准',approved:'已批准',dispatching:'发送中',sent:'已发送',rejected:'已拒绝',expired:'已失效',cancelled:'已取消',audit_failed:'审核失败',delivery_unknown:'发送结果未知'};
const usageStatus={running:'进行中',completed:'完成',failed:'失败'};
const time=n=>n?new Date(n).toLocaleString('zh-CN',{hour12:false}):'—';
const pill=(s,tone=false)=>`<span class="pill ${tone===true?'warn':tone||''}">${esc(s)}</span>`;
const empty=s=>`<div class="empty">${esc(s)}</div>`;
// Current group for pages that work on one group at a time.
const groupOf=()=>{const gs=state.config.groups;return gs.find(g=>g.id===groupSel)||gs.find(g=>g.enabled)||gs[0]||null;};
const groupSelect=(list=state.config.groups,current=groupOf())=>list.length>1?`<select class="group-select" data-group-select data-nodirty aria-label="选择群">${list.map(g=>`<option value="${esc(g.id)}" ${current?.id===g.id?'selected':''}>${esc(g.name)} · ${esc(g.private?g.id.slice(8):g.id)}${g.enabled?'':'（停用）'}</option>`).join('')}</select>`:'';
// The memory page also lists allowlisted private chats; their memories are kept apart from every group's.
const memGroups=()=>[...state.config.groups,...new Map(state.members.filter(m=>String(m.groupId).startsWith('private:')&&state.config.privateAllowlist.includes(m.userId)).map(m=>[m.groupId,{id:m.groupId,name:`私聊 · ${m.nickname||m.name||m.userId}`,enabled:true,private:true}])).values()];
const memGroupOf=()=>memGroups().find(g=>g.id===groupSel)||groupOf();
const noGroup=()=>`<section class="panel">${empty('还没有设置群聊。先到「连接与环境」填写机器人 QQ、审批 QQ 并添加群。')}<div class="row section"><button class="primary" data-tab="settings">去设置账号与群聊</button></div></section>`;
function setupSteps(){const c=state.config,s=state.connections,enabled=c.groups.filter(g=>g.enabled);return [
 {done:!!(s.httpUrl&&s.wsUrl&&s.tokenConfigured),label:'填写 OneBot 的 HTTP 地址、WebSocket 地址和 Token',tab:'settings'},
 {done:!!(c.botId&&c.ownerId),label:'填写机器人 QQ 和你自己的审批 QQ',tab:'settings'},
 {done:enabled.length>0,label:'添加并启用至少一个群',tab:'settings'},
 {done:state.connection.status==='connected',label:'连接状态变为「已连接」',tab:'settings'},
 {done:(state.modelCatalogs||[]).length>0,label:'检测可用模型（人格与模型 → 检测可用模型）',tab:'personas'},
 {done:enabled.length>0&&enabled.every(g=>c.personas[g.persona].prompt.trim()),label:'为启用群使用的人格填写设定',tab:'personas'}];}
const groupRow=(g={id:'',name:'',enabled:true,persona:'gpt'})=>`<div class="group-row" data-group-row><input name="gid" inputmode="numeric" placeholder="群号" aria-label="群号" value="${esc(g.id)}"><input name="gname" placeholder="群名称（只在后台显示）" aria-label="群名称" maxlength="40" value="${esc(g.name)}"><select name="gpersona" aria-label="使用的人格">${Object.entries(state.config.personas).map(([id,p])=>`<option value="${id}" ${g.persona===id?'selected':''}>${esc(p.name)}</option>`).join('')}</select><label class="check"><input type="checkbox" name="genabled" ${g.enabled?'checked':''}>启用</label><button type="button" class="small danger" data-group-remove>移除</button></div>`;
function toast(text,kind='ok'){const t=$('#toast');t.textContent=text;t.className='show '+kind;clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.className='',kind==='error'?10000:4500);}
async function api(path,method='GET',body){const r=await fetch('/api/'+path,{method,headers:{'Content-Type':'application/json','X-QQ-Friend':'1'},body:body===undefined?undefined:JSON.stringify(body)});const v=await r.json();if(!r.ok){if(r.status===401)login();if(r.status===404&&v.error==='接口不存在')throw new Error('后台服务还是旧版本，请重启服务后再使用这个功能');throw new Error(v.error||'请求失败');}return v;}
async function refresh(){state=await api('state');modelCatalogs.clear();for(const c of state.modelCatalogs||[])modelCatalogs.set(c.provider,c);render();}
// OneBot reconnects in the background after a connection or identity change; pick up its status shortly after.
function refreshSoon(){clearTimeout(refreshSoon.timer);refreshSoon.timer=setTimeout(()=>{if(state&&!dirty.size&&!document.querySelector('dialog[open]'))refresh().catch(()=>{});},2500);}
function leave(except){const other=[...dirty].filter(k=>k!==except);return !other.length||confirm('有尚未保存的修改，继续会丢失这些修改。确定继续吗？');}
function login(){state=null;dirty.clear();$('#app').innerHTML=`<form id="login" class="login"><div class="brand"><span class="logo">伴</span><div>QQ 群友<small>LOCAL COMPANION</small></div></div><h1>欢迎回来</h1><p class="lead">在本机管理一个有记忆、有分寸的群友</p><label for="token">管理密钥</label><input id="token" type="password" autocomplete="current-password" required placeholder="粘贴本地管理密钥"><p class="muted">首次启动请打开项目内的 <code>data/admin-token.txt</code><br>也可以使用「启动QQ群友.cmd」自动打开后台</p><button class="primary">进入控制台</button></form>`;$('#login').onsubmit=e=>{e.preventDefault();run(async()=>{await api('session','POST',{token:$('#token').value});await refresh();},e.submitter);};}
const head=(title,sub,action='')=>`<div class="page-head"><div><div class="eyebrow">COMPANION / ${esc(tab)}</div><h1>${title}</h1><p class="lead">${sub}</p></div>${action}</div>`;
function modelPicker(spec,key,modelName='model',effortName='effort',labelPrefix=''){
 const apiMode=spec.provider==='claude'&&spec.transport==='api',mode=spec.provider==='claude'?`<label>Claude 调用模式</label><select data-transport name="${modelName}Transport"><option value="native" ${!apiMode?'selected':''}>本地 Claude SDK</option><option value="api" ${apiMode?'selected':''}>API</option></select>`:'';
 if(apiMode)return `<div class="model-picker" data-provider="claude-api" data-key="${key}" data-model-name="${modelName}" data-effort-name="${effortName}">${mode}<div class="fields"><div><label for="${key}-model">API 模型 ID（可手填）</label><input id="${key}-model" name="${modelName}" data-model-select list="${key}-catalog" value="${esc(spec.model)}" required><datalist id="${key}-catalog"></datalist></div><div><label for="${key}-effort">API 推理强度（需模型支持）</label><select id="${key}-effort" name="${effortName}" data-effort-select>${['','low','medium','high','xhigh','max'].map(e=>`<option value="${e}" ${e===spec.effort?'selected':''}>${e||'不发送此参数'}</option>`).join('')}</select></div><div><label>提示词预设</label><select name="${modelName}Preset" data-api-preset>${(state.config.claudeApi?.presets||[{id:'default',name:'默认'}]).map(p=>`<option value="${esc(p.id)}" ${p.id===(spec.apiPreset||'default')?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div></div><div class="row section"><button type="button" class="small" data-model-detect="claude-api">检测 API 模型</button><span data-model-detected class="muted"></span></div><p data-model-note class="muted">兼容服务不提供模型列表时，可直接填写模型 ID；参数支持以服务说明为准。</p></div>`;
 return `<div class="model-picker" data-provider="${esc(spec.provider)}" data-key="${key}" data-model-name="${modelName}" data-effort-name="${effortName}">${mode}<div class="fields"><div><label for="${key}-model">${labelPrefix}模型 ID</label><select id="${key}-model" name="${modelName}" data-model-select><option value="${esc(spec.model)}">${esc(spec.model||'本地默认模型')}</option></select></div><div><label for="${key}-effort">${labelPrefix}推理强度</label><select id="${key}-effort" name="${effortName}" data-effort-select><option value="${esc(spec.effort)}">${esc(spec.effort||'使用本地默认设置')}</option></select></div></div><div class="row section"><button type="button" class="small" data-model-detect="${esc(spec.provider)}">检测可用模型</button><span class="muted" data-model-detected></span></div><p class="muted" data-model-note aria-live="polite"></p></div>`;
}
function fillModelPicker(el){
 const provider=el.dataset.provider,catalog=modelCatalogs.get(provider),model=el.querySelector('[data-model-select]'),effort=el.querySelector('[data-effort-select]');
 if(provider==='claude-api'){el.querySelector('datalist').innerHTML=(catalog?.models||[]).map(m=>`<option value="${esc(m.id)}">${esc(m.name)}</option>`).join('');el.querySelector('[data-model-detected]').textContent=catalog?`${catalog.models.length} 个 API 模型`:'';return;}
 const result=modelOptions(catalog,model.value,effort.value);
 model.innerHTML=result.models.map(m=>`<option value="${esc(m.id)}" ${m.unavailable?'disabled':''}>${esc(m.name)}${m.id&&!m.unavailable&&catalog?' · '+esc(m.id):''}</option>`).join('');model.value=result.model;model.disabled=!result.canSelectModel;
 effort.innerHTML=result.efforts.length?result.efforts.map(e=>`<option value="${esc(e)}">${esc(e)}</option>`).join(''):`<option value="${esc(result.effort)}">使用本地默认设置</option>`;effort.value=result.effort;effort.disabled=!result.canSelectEffort;
 const loading=modelLoads.has(provider),button=el.querySelector('[data-model-detect]');button.disabled=loading;button.textContent=loading?'检测中…':catalog?'重新检测':'检测可用模型';
 el.querySelector('[data-model-detected]').textContent=catalog?`${catalog.models.length} 个模型 · 检测于 ${time(catalog.fetchedAt)}`:'尚未检测';
 el.querySelector('[data-model-note]').textContent=[modelErrors.get(provider),result.note].filter(Boolean).join('；');
}
function bindRoleProviders(){const f=$('#roles-form');if(!f)return;for(const card of f.querySelectorAll('[data-background-role]')){const select=card.querySelector('[data-role-provider]'),drafts=new Map();let previous=select.value;
 select.onchange=()=>{const picker=card.querySelector('.model-picker');drafts.set(previous,{provider:previous,model:picker.querySelector('[data-model-select]').value,effort:picker.querySelector('[data-effort-select]').value,...pickerMode(picker)});const provider=select.value,role=card.dataset.backgroundRole;
  const persona=state.config.personas[{codex:'gpt',claude:'claude',deepseek:'deepseek'}[provider]],spec=drafts.get(provider)||{...(provider==='claude'?{transport:persona.transport||'native',apiPreset:persona.apiPreset||'default'}:{}),provider,model:provider==='codex'?'gpt-6.1-sol':persona.model,effort:provider==='codex'?'low':persona.effort};
  picker.outerHTML=modelPicker(spec,'role-'+role,role+'Model',role+'Effort');previous=provider;bindModelPickers();};}}
function pickerMode(el){return el?.querySelector('[data-transport]')?{transport:el.querySelector('[data-transport]').value,apiPreset:el.querySelector('[data-api-preset]')?.value||'default'}:{};}
function bindModelPickers(){
 for(const el of document.querySelectorAll('.model-picker')){const mode=el.querySelector('[data-transport]');if(mode)mode.onchange=()=>{const transport=mode.value,spec={provider:'claude',transport,model:transport==='api'?'':state.config.personas.claude.transport==='api'?'claude-fable-5-1':state.config.personas.claude.model,effort:transport==='api'?'':'medium'};el.outerHTML=modelPicker(spec,el.dataset.key,el.dataset.modelName,el.dataset.effortName);bindModelPickers();};}

 for(const el of document.querySelectorAll('.model-picker')){fillModelPicker(el);el.querySelector('[data-model-select]').onchange=()=>{fillModelPicker(el);};}
 for(const b of document.querySelectorAll('[data-model-detect]'))b.onclick=()=>run(async()=>{
  const provider=b.dataset.modelDetect;if(modelLoads.has(provider))return;modelLoads.add(provider);modelErrors.delete(provider);
  const busy=()=>{for(const el of document.querySelectorAll('.model-picker'))if(el.dataset.provider===provider){const button=el.querySelector('[data-model-detect]');button.disabled=modelLoads.has(provider);button.textContent=modelLoads.has(provider)?'检测中…':modelCatalogs.has(provider)?'重新检测':'检测可用模型';}};busy();
  try{const catalog=await api('models','POST',{provider});modelCatalogs.set(provider,catalog);for(const el of document.querySelectorAll('.model-picker'))if(el.dataset.provider===provider)fillModelPicker(el);toast(`已检测到 ${catalog.models.length} 个模型，选择后保存生效`);}
  catch(e){modelErrors.set(provider,e.message);for(const el of document.querySelectorAll('.model-picker'))if(el.dataset.provider===provider)el.querySelector('[data-model-note]').textContent=`检测失败：${e.message}；已有选择保留`;throw e;}
  finally{modelLoads.delete(provider);busy();}
 });
}
function render(){if(!state)return;const c=state.config,same=tab===lastTab,y=scrollY,listY=$('.member-scroll')?.scrollTop,pending=[...state.memories,...(state.memoryChanges||[])].filter(m=>m.status==='pending').length;
 $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="logo">伴</span><div>QQ 群友<small>LOCAL COMPANION</small></div></div><nav class="nav">${Object.entries(labels).map(([id,name],i)=>`<button data-tab="${id}" class="${tab===id?'active':''}" ${tab===id?'aria-current="page"':''}><span class="num">${String(i+1).padStart(2,'0')}</span>${name}${id==='memory'&&pending?`<span class="badge-count" title="待审核">${pending}</span>`:''}${id==='proactive'&&state.proposals.some(p=>p.status==='pending')?`<span class="badge-count" title="待批准">${state.proposals.filter(p=>p.status==='pending').length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-foot"><span class="side-dot ${state.connection.status==='connected'?'':'off'}"></span>${state.connection.status==='connected'?'QQ 已连接':'QQ 未连接'}<br>机器人 · ${esc(c.botId||'未设置')}<br>v0.3.2 / LOCAL FIRST</div></aside><main class="main"><header class="topbar"><span class="crumb">控制台 <span class="muted"> / </span> ${labels[tab]}</span><div class="actions">${pill(c.debug?'调试模式 · 发给自己':'正式模式 · 发到群',!c.debug)}${pill(c.paused?'已暂停':'运行中',c.paused)}<button class="small" data-action="refresh">刷新</button><button class="small ${c.paused?'primary':'danger'}" data-action="runtime">${c.paused?'启动群友':'暂停全部'}</button></div></header><div id="page">${views[tab]()}</div></main></div><dialog id="history-dialog" class="dialog wide"><div class="dialog-head"><h2>修改历史</h2><form method="dialog"><button class="small">关闭</button></form></div><div id="history"></div></dialog>`;
 dirty.clear();lastTab=tab;bind();
 for(const d of document.querySelectorAll('details[data-k]'))if(openState.has(d.dataset.k))d.open=openState.get(d.dataset.k);
 if(same){scrollTo(0,y);const l=$('.member-scroll');if(l&&listY)l.scrollTop=listY;}else scrollTo(0,0);
 const l=$('.member-scroll'),a=l?.querySelector('.member-button.active');if(a&&(a.offsetTop<l.scrollTop||a.offsetTop+a.offsetHeight>l.scrollTop+l.clientHeight))l.scrollTop=a.offsetTop-l.clientHeight/3;
}
function overview(){const c=state.config,ready=c.groups.length>0&&c.groups.every(g=>c.personas[g.persona].prompt.trim()),calls=state.callsToday??state.usage.filter(u=>u.startedAt>Date.now()-86400000).length,limit=c.participation.dailyCalls,memoryPending=[...state.memories,...(state.memoryChanges||[])].filter(m=>m.status==='pending').length,steps=setupSteps(),left=steps.filter(s=>!s.done).length;return head('让群聊，自然发生','观察、记住、参与。每一个主动话题，都先由你把关。')+(left?`<section class="panel setup"><div class="row between"><h2>首次设置 · 还差 ${left} 步</h2><span class="muted">完成后点右上角「启动群友」；调试模式下回复只发到你的私聊</span></div><ol class="steps">${steps.map(s=>`<li class="${s.done?'done':''}"><span class="step-mark">${s.done?'✓':''}</span><span class="grow">${esc(s.label)}</span>${s.done?'':`<button class="small" data-tab="${s.tab}">去设置</button>`}</li>`).join('')}</ol></section>`:'')+`<div class="grid"><div class="panel"><div class="muted">QQ 连接</div><div class="metric compact">${state.connection.status==='connected'?'已连接':'等待连接'}</div><span class="status-dot ${state.connection.status==='connected'?'live':''}"></span><span class="muted">${esc(state.connection.note)}</span></div><div class="panel"><div class="muted">今日模型调用</div><div class="metric">${calls.toLocaleString()}<small> / ${limit===-1?'不限':`${limit.toLocaleString()} 次`}</small></div>${limit===-1?'':`<div class="bar"><i class="w${Math.min(10,Math.ceil(calls/limit*10))}"></i></div>`}<span class="muted">包含观察、记忆、审核与回复 · 滚动 24 小时</span><br><button class="link" data-tab="settings" data-focus="dailyCalls">调整上限 →</button></div><div class="panel"><div class="muted">等待你的审核</div><div class="metric">${state.proposals.filter(p=>p.status==='pending').length}<small> 个主动话题</small></div><button class="link" data-tab="proactive">查看候选与完整文案 →</button>${memoryPending?`<br><button class="link" data-tab="memory" data-mem-filter="pending">另有 ${memoryPending} 项记忆待审核 →</button>`:''}</div></div><div class="grid two section"><section class="panel"><div class="row between"><h2>正在陪伴的群</h2>${pill(`${c.groups.filter(g=>g.enabled).length} 个启用`)}</div>${c.groups.length?'':empty('还没有添加群聊')}${c.groups.map(g=>`<div class="notice-line"><div class="row"><div class="avatar ${g.persona}">${esc(c.personas[g.persona].name[0])}</div><div><strong>${esc(g.name)}</strong><div class="muted">${g.id} · ${esc(c.personas[g.persona].name)}</div></div></div>${pill(g.enabled?'已启用':'停用',!g.enabled)}</div>`).join('')}<div class="hint ${ready?'':'warn'}">${ready?'人格已设置。可以在后台切换模型与人格。':'人格设定还是空的。填写启用群使用的人格后，才能启动自动回复。'}</div><button data-tab="personas">设置人格</button></section><section class="panel"><h2>运行约定</h2><div class="notice-line"><span>正常接话</span><span class="muted">观察后自动回复</span></div><div class="notice-line"><span>新话题与推荐</span><span class="muted">agent 审核 → 你的私聊批准</span></div><div class="notice-line"><span>私聊白名单</span><code>${c.privateAllowlist.join('、')||'未设置'}</code></div><div class="notice-line"><span>QQ 中更改配置 / 执行任务</span>${pill('不开放')}</div></section></div><section class="panel section"><div class="row between"><h2>最近活动</h2><span class="muted">不展示模型内部推理</span></div>${state.logs.slice(0,8).map(l=>`<div class="activity ${l.type==='error'?'error-line':''}"><span class="time">${new Date(l.updated).toLocaleTimeString('zh-CN')}</span><div>${esc(l.message)}</div></div>`).join('')||empty('还没有运行记录。配置连接后，群友将在这里留下简短的活动记录。')}</section>`;}
function memory(){const g=memGroupOf();if(!g)return head('群友与记忆','按需调用事实，让每次更新都有来源、版本和审核。')+noGroup();return head('群友与记忆','按需调用事实，让每次更新都有来源、版本和审核。',`<div class="row">${groupSelect(memGroups(),g)}<button data-open-dialog="memory-settings-dialog">检索设置</button>${g.private?'':'<button data-action="sync-members">从 QQ 同步群友</button>'}</div>`)+memoryPage(state,{...memUi,member,groupId:g.id},{esc,time,pill,empty})+memorySettings(state);}
function personas(){
 const c=state.config,p=c.personas[persona];
 return head('人格与模型','三种独立人格，共享群内事实，保留各自的互动记忆。')+`
 <section class="panel"><div class="segmented wide">${Object.entries(c.personas).map(([id,v])=>`<button data-persona="${id}" class="${persona===id?'active':''}" aria-pressed="${persona===id}">${esc(v.name)}${c.groups.some(g=>g.persona===id)?'<b>使用中</b>':''}${v.prompt.trim()?'':'<b class="warn">未填写</b>'}</button>`).join('')}</div>
 <form id="persona-form"><div class="fields"><div><label for="persona-name">人格名称</label><input id="persona-name" name="name" value="${esc(p.name)}" required></div><div><label for="persona-provider">对应后端</label><input id="persona-provider" value="${esc(p.provider)}" disabled></div></div>
 ${modelPicker(p,'persona')}
 <label for="persona-prompt">人格设定 <span class="muted" data-count-for="persona-prompt">${p.prompt.length} / 12000 字</span></label><textarea id="persona-prompt" name="prompt" rows="12" maxlength="12000" placeholder="暂留白。你可以填写角色背景、语气、互动方式和回复示例。">${esc(p.prompt)}</textarea>
 <label for="persona-brief">观察员看到的简介（可选，最多 300 字） <span class="muted">只用来判断要不要接话，能省下每次判断时的完整人格；留空时取人格设定的前 300 字</span></label><textarea id="persona-brief" name="brief" rows="3" maxlength="300" placeholder="例如：嘴毒但心软的群友，爱聊游戏和动漫，不爱长篇大论">${esc(p.brief||'')}</textarea><button class="primary section">保存 ${esc(p.name)} 人格</button></form></section>
 <section class="panel"><h2>每个群使用谁</h2><form id="active-persona">${c.groups.length?'':empty('还没有添加群聊，先到「连接与环境」设置。')}${c.groups.map(g=>`<label>${esc(g.name)} · ${g.id}</label><select name="${g.id}">${Object.entries(c.personas).map(([id,v])=>`<option value="${id}" ${g.persona===id?'selected':''}>${esc(v.name)}</option>`).join('')}</select>`).join('')}<p class="muted">切换会取消旧任务和未发送回复，并使旧审批失效。</p><button class="primary section">切换群人格</button></form></section>
 <section class="panel"><h2>后台 agent</h2><p class="muted">每个角色独立选择 provider、模型和推理强度；同一 provider 也可以使用不同模型。</p><form id="roles-form"><div class="grid two">${Object.entries(backgroundRoles).map(([id,name])=>{const spec=backgroundSpecs(c)[id];return `<section class="panel" data-background-role="${id}"><h3>${name}</h3><label for="role-${id}-provider">模型提供方</label><select id="role-${id}-provider" data-role-provider name="${id}Provider">${Object.entries(providerNames).map(([provider,label])=>`<option value="${provider}" ${spec.provider===provider?'selected':''}>${label}</option>`).join('')}</select>${modelPicker(spec,'role-'+id,id+'Model',id+'Effort')}</section>`;}).join('')}</div>
 <p class="muted">观察员默认 GPT 6.1 Sol / low（轻量）。DeepSeek 仅支持文本；选择它观察群聊时，图片与视频预读使用 GPT 6.1 Sol / low，计入调用预算。各角色使用独立会话；模型和强度来自实际检测结果，保存后生效。</p><button class="primary section">保存后台模型</button></form></section>`;
}

function proactive(){const c=state.config;return head('主动话题','先独立审核，再发到你的私聊；批准后才进入发送队列。',groupSelect())+`<section class="panel"><h2>候选与审批</h2>${state.proposals.map(p=>`<article class="memory-card ${p.status==='pending'?'pending':''}"><div class="card-head">${pill(proposalStatus[p.status]||p.status,p.status==='pending'?true:['sent','approved'].includes(p.status)?false:'mute')}<span class="muted">${esc(state.config.personas[p.persona]?.name)} · ${p.groupId}${p.debug?' · 调试':''}</span><code class="grow end-text">${p.code}</code></div>${p.parts.map(x=>`<div class="bubble">${esc(x)}</div>`).join('')}<p class="muted">审核：${esc(p.auditReason||'正在处理')}</p><p class="muted">私聊预览：${p.noticeDelivered?'已送达':'未确认送达'} · 有效至 ${time(p.expiresAt)}</p>${p.sources.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noreferrer">${esc(s.title||s.url)}</a>`).join('<br>')}${p.status==='pending'?`<div class="row section"><button class="small primary" data-approve="${p.code}">批准当前文案</button><button class="small" data-reject="${p.code}">拒绝</button></div>`:''}</article>`).join('')||empty('还没有候选话题。启用后，系统会在预算和安静时段之外寻找适合分享的内容。')}</section><section class="panel"><h2>主动参与设置</h2><form id="proactive-form"><label class="check"><input type="checkbox" name="enabled" ${c.proactive.enabled?'checked':''}>允许主动开启话题</label><div class="fields">${[['intervalMinutes','发现间隔（分钟）',15,1440],['maxDaily','每天最多候选数',1,30],['approvalMinutes','审批有效期（分钟）',1,1440],['quietStart','安静时段开始（小时）',0,23],['quietEnd','安静时段结束（小时）',0,23]].map(([k,n,a,b])=>`<div><label>${n}</label><input name="${k}" type="number" min="${a}" max="${b}" value="${c.proactive[k]}"></div>`).join('')}<div><label>时区</label><input name="timezone" value="${esc(c.proactive.timezone)}"></div></div><button class="primary section">保存主动参与设置</button></form></section><section class="panel"><details data-k="manual-proposal"><summary>手动提交候选，验证双审流程</summary><form id="proposal-form"><p class="muted">提交到：${esc(groupOf()?.name||'尚未设置群')}${groupOf()?` · ${esc(groupOf().id)}`:''}</p><label>拟发送内容</label><textarea name="text" required maxlength="2000"></textarea><label>来源链接（可空，支持哔哩哔哩 / X）</label><input name="url" type="url"><label>来源摘录</label><textarea name="excerpt"></textarea><button class="primary section">提交给审核 agent</button></form></details></section>`;}
function messages(){const c=state.config;return head('消息与调试','原文、发送回执和调试预览放在一起，方便核对。',groupSelect())+`<div class="grid two"><section class="panel"><h2>输出规则</h2><form id="output-form"><label>按这些标点分条</label><input name="splitOn" value="${esc(c.output.splitOn.replace(/\n/g,'\\n'))}"><label>移除这些句尾标点</label><input name="stripEnd" value="${esc(c.output.stripEnd)}"><div class="fields">${[['maxParts','最多条数',1,10],['maxPartChars','单条字符上限',20,1000],['delayMs','发送间隔（毫秒）',0,10000]].map(([k,n,a,b])=>`<div><label>${n}</label><input type="number" name="${k}" min="${a}" max="${b}" value="${c.output[k]}"></div>`).join('')}</div><label class="check"><input type="checkbox" name="debug" ${c.debug?'checked':''}>调试模式：回复发到我的 QQ</label><button class="primary section">保存规则</button></form></section><section class="panel"><h2>预览工作台</h2><form id="preview-form"><label>测试文本 / 模拟群消息</label><textarea name="text" data-nodirty placeholder="我觉得可以。先看看大家什么时候有空，再决定去哪。" required></textarea><div class="row section"><button data-preview-type="format" type="button">只看拆句效果</button><button data-preview-type="model" type="button" class="primary">模型回复预览</button></div></form><p class="muted">预览只显示在这里，不会发到 QQ，也不写入正式记忆。模型预览使用「${esc(groupOf()?.name||'尚未设置群')}」的人格和上下文，会计入用量。</p><div id="preview-output"></div></section></div><section class="panel section"><div class="row between"><h2>最近消息</h2><span class="muted">最近 ${Math.min(25,state.messages.length)} 条，最新在下</span></div><div class="message-log">${state.messages.slice(0,25).reverse().map(m=>`<div class="message ${m.direction==='out'?'out':''}"><small>${esc(m.name)} · ${m.groupId} · ${time(m.at)} ${m.debug?'· 调试':''}</small>${esc(m.text)}</div>`).join('')||empty('尚未收到允许群或白名单成员的消息。')}</div></section><section class="panel"><h2>发送记录</h2>${state.outbox.length?`<div class="table-wrap scroll"><table><thead><tr><th>时间</th><th>类型</th><th>状态</th><th>目标群</th><th>回执 / 说明</th></tr></thead><tbody>${state.outbox.map(o=>`<tr><td>${time(o.createdAt)}</td><td>${outboxCategory[o.category]||esc(o.category)}${o.debug?' · 调试':''}</td><td>${pill(outboxStatus[o.status]||o.status,o.status==='unknown'?'red':o.status==='sent'?false:'mute')}</td><td>${o.groupId}</td><td>${esc(o.note||o.receipts?.join(',')||'—')}</td></tr>`).join('')}</tbody></table></div>`:empty('还没有发送记录。')}</section>`;}
function browser(){return head('浏览器发现','从你已登录的 Chrome 页面寻找兴趣点，推荐始终需要双审。')+`<section class="panel"><h2>连接现有 Chrome</h2><p>在 Chrome 的扩展程序页面开启开发者模式，选择“加载已解压的扩展程序”，加载本项目的 <code>browser-extension</code> 文件夹。</p><p class="muted">打开扩展面板后填写配对信息。仅读取你打开的哔哩哔哩和 X 页面中已渲染的内容；不会提取 Cookie，不会点赞、评论或发帖。</p><div class="row section"><button data-action="pairing">显示配对信息</button><button data-action="toggle-browser" class="primary">${state.config.browser.enabled?'暂停浏览器接入':'启用浏览器接入'}</button>${pill(state.config.browser.enabled?'接入已启用':'接入已暂停',!state.config.browser.enabled)}</div><div id="pairing"></div></section><section class="panel"><h2>已发现内容 · ${state.feeds.length}</h2>${state.feeds.map(f=>`<article class="memory-card"><a href="${esc(f.url)}" target="_blank" rel="noreferrer">${esc(f.title||f.url)}</a><p class="memory-text clamp">${esc(f.text.slice(0,500))}</p><div class="muted">${time(f.readAt)} · Chrome 已渲染内容</div></article>`).join('')||empty('尚未接收浏览内容。加载并配对扩展后，在已登录的哔哩哔哩或 X 页面采集。')}</section>`;}
// Average input tokens and the cached share per call, to see where a role's tokens go.
// Whole prompt including cache reads/writes: Anthropic counts those outside inputTokens, OpenAI-style providers inside.
const promptOf=t=>Number.isFinite(t?.totalTokens)&&Number.isFinite(t?.outputTokens)?t.totalTokens-t.outputTokens:t?.inputTokens;
const tokenMix=list=>{const t=list.map(x=>x.tokens).filter(x=>Number.isFinite(promptOf(x)));if(!t.length)return '';const input=t.reduce((n,x)=>n+promptOf(x),0),cached=t.reduce((n,x)=>n+(x.cachedInputTokens||0),0);return ` <small class="muted">平均输入 ${Math.round(input/t.length).toLocaleString()} · 缓存 ${Math.round(cached/Math.max(1,input)*100)}%</small>`;};
// Observer calls by mode. Only the uncached part of the input is billed at full price, so that is the headline number.
function sessionPanel(rows){const obs=rows.filter(r=>r.role==='observer'&&r.status==='completed'&&Number.isFinite(promptOf(r.tokens)));
 const cells=[['DeepSeek 长会话',r=>r.transport==='session'],['DeepSeek 单次',r=>r.provider==='deepseek'&&r.transport!=='session'],['Codex 单次',r=>r.provider==='codex'],['Claude 单次',r=>r.provider==='claude']].map(([name,f])=>{const list=obs.filter(f);if(!list.length)return '';const avg=g=>Math.round(list.reduce((n,r)=>n+g(r.tokens),0)/list.length),input=avg(promptOf),uncached=avg(t=>promptOf(t)-(t.cachedInputTokens||0));
  return `<div class="panel stat"><span class="muted">${name} · ${list.length} 次</span><div class="metric compact">${uncached.toLocaleString()}</div><span class="muted">未缓存输入 / 次 · 总输入 ${input.toLocaleString()} · 缓存 ${Math.round((1-uncached/Math.max(1,input))*100)}%</span></div>`;}).join('');
 return cells?`<section class="panel section"><div class="row between"><h2>观察员：长会话 vs 单次</h2><button class="link" data-tab="settings" data-focus="observerSession">长会话设置 →</button></div><p class="muted">最近记录的观察员调用平均。缓存命中的输入很便宜（DeepSeek 约为未命中的 1/50），主要看未缓存的部分。</p><div class="grid four">${cells}</div></section>`:'';}
// Today's wake counters: replies that skipped the observer, observer calls, and chatter held back by the rate limit.
function wakePanel(rows){const today=(state.wakeStats||[])[0],obs=rows.filter(r=>r.role==='observer'&&r.startedAt>Date.now()-86400000);
 return `<section class="panel section"><div class="row between"><h2>点名与观察员（今天）</h2><button class="link" data-tab="settings" data-focus="observerMinGapSeconds">调整频率 →</button></div><div class="grid four">${[['直接回复',today?.direct||0,'被点名，跳过观察员'],['观察员判断',today?.judged||0,'闲聊批次'],['推迟',today?.deferred||0,'超出频率，等下一个空档'],['观察员调用（24 小时）',obs.length,tokenMix(obs).replace(/<[^>]+>/g,'').trim()||'暂无 token 数据']].map(([a,b,c])=>`<div class="panel stat"><span class="muted">${a}</span><div class="metric compact">${b}</div><span class="muted">${esc(c)}</span></div>`).join('')}</div>${today?'':'<p class="muted">今天还没有计数：重启到新版本后开始统计。</p>'}</section>`;}
function usage(){const rows=state.usage,complete=rows.filter(u=>u.status==='completed'),known=complete.filter(u=>u.tokens?.totalTokens!=null);const roles=[...new Set(rows.map(u=>u.role))];return head('用量与预算','真实报告、缺失数据与账户额度分别展示。')+`<div class="grid"><div class="panel"><span class="muted">最近记录的调用</span><div class="metric">${rows.length}</div><span class="muted">${complete.length} 次完成 · ${rows.filter(u=>u.status==='failed').length} 次失败</span></div><div class="panel"><span class="muted">已知 token 总量</span><div class="metric">${known.length?known.reduce((n,u)=>n+u.tokens.totalTokens,0).toLocaleString():'未知'}</div><span class="muted">覆盖 ${known.length} / ${complete.length} 次完成调用，非账单金额</span></div><div class="panel"><span class="muted">后台调用预算</span><div class="metric">${state.config.participation.dailyCalls===-1?'不限':state.config.participation.dailyCalls.toLocaleString()}<small>${state.config.participation.dailyCalls===-1?'':' 次 / 滚动 24 小时'}</small></div><span class="muted">过去 24 小时已用 ${(state.callsToday??0).toLocaleString()} 次 · 未发言的观察也计入调用</span></div></div>${wakePanel(rows)}${sessionPanel(rows)}<section class="panel section"><h2>按职责</h2>${roles.map(r=>{const subset=rows.filter(x=>x.role===r),known=subset.filter(x=>x.tokens?.totalTokens!=null),failed=subset.filter(x=>x.status==='failed').length;return `<div class="notice-line"><span>${esc(role(r))} <span class="muted">${esc(r)}</span></span><span>${subset.length} 次${failed?` · <span class="error">${failed} 次失败</span>`:''} · ${known.length?known.reduce((n,x)=>n+x.tokens.totalTokens,0).toLocaleString()+' token':'token 未知'} <small class="muted">（用量覆盖 ${known.length}/${subset.length} 次）</small>${tokenMix(subset)}</span></div>`;}).join('')||empty('还没有模型调用。')}</section><section class="panel"><div class="row between"><h2>账户额度</h2><button class="small" data-action="quota">刷新 GPT 额度</button></div><p class="muted">账户总额度还会被你其他客户端使用。Claude / DeepSeek 没有已验证的额度读数时保持未知。</p>${state.quotas.map(q=>`<p class="muted">${q.provider} · 更新于 ${time(q.fetchedAt)}</p><pre>${esc(JSON.stringify(q.rateLimitsByLimitId||q.rateLimits,null,2))}</pre>`).join('')||empty('尚未读取账户额度')}</section>${budgetPanel(rows,{esc,time,empty,role})}<section class="panel"><div class="row between"><h2>调用记录</h2><span class="muted">${rows.length} 条</span></div>${rows.length?`<div class="table-wrap scroll"><table><thead><tr><th>时间</th><th>职责 / 群</th><th>模型</th><th>状态</th><th>Token</th><th>耗时</th></tr></thead><tbody>${rows.map(r=>`<tr class="${r.status==='failed'?'failed':''}"><td>${time(r.startedAt)}</td><td>${esc(role(r.role))}<br><span class="muted">${esc(r.groupId)}</span></td><td>${esc(r.model)}<br><span class="muted">${esc(r.effort)}${r.transport==='api'?' · API':''}</span></td><td>${esc(usageStatus[r.status]||r.status)}${r.error?`<div class="error">${esc(r.error)}</div>`:''}</td><td>${r.tokens?.totalTokens?.toLocaleString()??'未知'}</td><td>${r.durationMs?Math.round(r.durationMs/1000)+'s':'—'}</td></tr>`).join('')}</tbody></table></div>`:empty('还没有模型调用。')}</section>`;}
// Fallback for a server older than the wake settings; newer servers send c.wake with its defaults filled in.
const WAKE_FALLBACK={directReply:true,names:[],keywords:[],batchMs:8000,unfinishedMs:12000,observerMinGapSeconds:15,observerHourly:60,observerMessages:16,stickerEvery:3,stickerHourly:6,observerSession:false,observerSessionTurns:30,observerSessionMaxTokens:40000,botAccounts:[],botExchanges:2,eagerness:'normal',conversationSeconds:120,conversationTurns:8};
function settings(){const c=state.config,s=state.connections,wk={...WAKE_FALLBACK,...c.wake},observer=c.roleModels[c.roles.observer]||{};return head('连接与环境','连接凭据仅保存在本机，不会传入聊天模型。')+`<section class="panel"><div class="row between"><h2>OneBot 11 连接${c.botId?` · ${esc(c.botId)}`:''}</h2>${pill(state.connection.status==='connected'?'已连接':esc(state.connection.status),state.connection.status!=='connected')}</div><form id="connection-form"><div class="fields"><div><label>HTTP 地址</label><input name="httpUrl" value="${esc(s.httpUrl)}" placeholder="http://127.0.0.1:3000"></div><div><label>事件 WebSocket 地址</label><input name="wsUrl" value="${esc(s.wsUrl)}" placeholder="ws://127.0.0.1:3001"></div><div><label>HTTP Token ${s.tokenConfigured?'· 已保存':''}</label><input type="password" name="token" placeholder="留空保留已有值" autocomplete="new-password"></div><div><label>WebSocket Token ${s.wsTokenConfigured?'· 已保存':''}</label><input type="password" name="wsToken" placeholder="留空保留已有值" autocomplete="new-password"></div></div><details data-k="harness-paths"><summary>本地 harness 路径</summary><label>Claude SDK 文件</label><input name="claudeSdk" value="${esc(s.claudeSdk)}"><label>DeepSeek 启动器</label><input name="deepseekCommand" value="${esc(s.deepseekCommand)}"><label>Wander 地址（读取 B站 / YouTube 链接）</label><input name="wanderUrl" value="${esc(s.wanderUrl||"")}" placeholder="http://127.0.0.1:4893"><label>Wander 令牌 ${s.wanderTokenConfigured?"· 已保存":""}</label><input type="password" name="wanderToken" placeholder="Wander 的 data/secrets.json 里的 linkToken；留空保留" autocomplete="new-password"></details><div class="row section"><button class="primary">保存并重连</button><button type="button" data-action="probe">只读检测账号</button><button type="button" data-action="event-setup">HTTP 事件推送配置</button></div><div id="connection-result"></div></form></section>
 <section class="panel" id="identity"><div class="row between"><h2>QQ 账号、白名单与群聊</h2><button type="button" class="small" data-action="whoami">检测 OneBot 登录的 QQ</button></div><form id="identity-form"><div class="fields"><div><label for="bot-id">机器人 QQ（OneBot 里登录的那个号）</label><input id="bot-id" name="botId" inputmode="numeric" placeholder="例如 123456789" value="${esc(c.botId)}"></div><div><label for="owner-id">审批 QQ（你自己的号：接收调试回复和审批）</label><input id="owner-id" name="ownerId" inputmode="numeric" placeholder="不能和机器人 QQ 相同" value="${esc(c.ownerId)}"></div></div>
 <label for="allowlist">私聊白名单（每行或用逗号分隔一个 QQ；审批 QQ 会自动加入）</label><textarea id="allowlist" name="allowlist" rows="3" placeholder="只有名单里的人私聊机器人才会被处理">${esc(c.privateAllowlist.filter(x=>x!==c.ownerId).join('\n'))}</textarea>
 <p class="muted">不在白名单里的私聊在存储和模型调用前就被丢弃。白名单成员的私聊只用于普通聊天和审批指令，不能修改配置或执行任务。</p>
 <h3 class="section">群聊</h3><p class="muted">只有启用的群会被观察和接话。群名称只在后台显示。</p><div class="group-rows" data-group-rows>${c.groups.map(groupRow).join('')}</div><p class="muted" data-group-empty ${c.groups.length?'hidden':''}>还没有群。点「添加群」手动填写，或从 QQ 读取机器人已加入的群。</p>
 <div class="row"><button type="button" class="small" data-group-add>＋ 添加群</button><button type="button" class="small" data-action="group-list">从 QQ 读取群列表</button></div><div id="group-picker"></div>
 <p class="muted section">保存会取消旧任务、未发送回复和待审批话题。</p><button class="primary">保存账号与群聊</button></form></section>
 <section class="panel"><h2>权限边界</h2><div class="notice-line"><span>审批 QQ</span><code>${esc(c.ownerId||'未设置')}</code></div><div class="notice-line"><span>私聊白名单</span><code>${esc(c.privateAllowlist.join('、')||'未设置')}</code></div><div class="notice-line"><span>启用群</span><code>${esc(c.groups.filter(g=>g.enabled).map(g=>g.id).join('、')||'未设置')}</code></div><div class="notice-line"><span>QQ 指令切换人格、模型、权限</span>${pill('禁止')}</div><div class="notice-line"><span>任意命令 / 编程任务</span>${pill('禁止')}</div></section><section class="panel"><h2>点名与观察员</h2><p class="muted">被 @、回复机器人、叫到名字或命中关键词时直接回复，不再先问观察员；其余闲聊先攒成一批，观察员按下面的频率上限判断要不要接话，超出上限时推迟到下一个空档，不会丢弃。观察员只看上次判断之后的新消息，再加之前 4 条作为上下文。</p>
 <form id="wake-form"><label class="check"><input type="checkbox" name="directReply" ${wk.directReply?'checked':''}>被点名时直接回复（跳过观察员）</label><div class="fields"><div><label>机器人的名字或昵称（每行一个，群友这样叫它时算点名）</label><textarea name="names" rows="2" placeholder="例如：小团子">${esc(wk.names.join('\n'))}</textarea></div><div><label>直接回复的关键词（每行一个，可留空）</label><textarea name="keywords" rows="2">${esc(wk.keywords.join('\n'))}</textarea></div>${[['observerMinGapSeconds','观察员最短间隔（秒）',0,3600],['observerHourly','观察员每小时最多判断几次',1,120],['batchMs','闲聊合并窗口（毫秒）',1000,60000],['unfinishedMs','话像没说完时的合并窗口（毫秒）',1000,60000],['observerMessages','观察员最多看几条消息',6,40],['stickerEvery','至少隔几次回复才发一次表情包',1,20],['stickerHourly','每小时最多发几次表情包',0,60]].map(([k,n,a,b])=>`<div><label>${n}</label><input name="${k}" type="number" min="${a}" max="${b}" value="${wk[k]}"></div>`).join('')}</div>
 <h3 class="section">活跃度与对话模式</h3><div class="fields"><div><label>活跃度（观察员多主动接话）</label><select name="eagerness">${[['quiet','安静：只在很自然时接话'],['normal','正常：能接就接，不必等点名'],['lively','活跃：不习惯性潜水，常插话']].map(([v,n])=>`<option value="${v}" ${wk.eagerness===v?'selected':''}>${n}</option>`).join('')}</select></div><div><label>对话等待（秒，0 = 不进入对话模式）</label><input name="conversationSeconds" type="number" min="0" max="600" value="${wk.conversationSeconds}"></div><div><label>每段对话最多回复几次</label><input name="conversationTurns" type="number" min="1" max="30" value="${wk.conversationTurns}"></div></div><p class="muted">机器人回复某人之后进入对话模式：和它聊天的人接着说时立刻判断（不受观察员间隔限制，冷却缩短到合并窗口），直到这么多秒内双方都没再说话、回复次数用完、或观察员判断对话已经结束。观察员每次还会看到最近 1 小时你和群友各说了多少、近 5 分钟有多热闹。</p>
 <h3 class="section">群里的其他机器人</h3><p class="muted">这些 QQ 号的消息照样作为上下文（标为机器人），但不会直接叫醒群友，也不会顶掉正在回复真人的消息；连续回应它们达到次数后，等真人说话才会再回应，避免两个机器人来回刷屏。也可以在「群友与记忆」里点成员的「标记为机器人」。</p><div class="fields"><div><label>机器人的 QQ 号（每行一个）</label><textarea name="botAccounts" rows="2" inputmode="numeric" placeholder="例如：123456789">${esc(wk.botAccounts.join('\n'))}</textarea></div><div><label>最多连续回应其他机器人几次（0 = 从不回应）</label><input name="botExchanges" type="number" min="0" max="10" value="${wk.botExchanges}"></div></div>
 <h3 class="section">观察员长会话</h3><label class="check"><input type="checkbox" name="observerSession" ${wk.observerSession?'checked':''}>每个群保持一个 DeepSeek 观察会话，每轮只发新消息</label><p class="muted">之前发过的内容走 DeepSeek 的前缀缓存，只有新消息按全价计。改了人格简介、观察员模型或机器人账号、到达下面的轮数或上下文上限、或闲置一小时后，自动换新会话。${observer.provider==='deepseek'?'':`<span class="error">当前观察员是 ${esc(observer.provider||'未设置')}，此开关只对 DeepSeek 观察员生效；可在「人格与模型」把观察员换成 DeepSeek（简单判断用 flash 即可）。</span>`}</p>
 <div class="fields">${[['observerSessionTurns','每个会话最多几轮',2,200],['observerSessionMaxTokens','会话上下文上限（token）',4000,200000]].map(([k,n,a,b])=>`<div><label>${n}</label><input name="${k}" type="number" min="${a}" max="${b}" value="${wk[k]}"></div>`).join('')}</div><button class="primary section">保存点名与观察员设置</button></form></section>
 <section class="panel"><h2>参与频率与预算</h2><form id="budget-form"><div class="fields">${[['debounceMs','消息合并窗口（毫秒）',500,30000],['cooldownSeconds','回复冷却（秒）',0,3600],['maxContextMessages','最多上下文消息',5,150],['maxContextChars','最终输入字符上限（含人格和媒体文字）',2000,50000],['maxReplyAgeSeconds','回复有效期（秒）',10,600],['dailyCalls','每天模型调用上限（-1 为不限）',-1,10000],['hourlyReplies','每小时回复上限',1,100]].map(([k,n,a,b])=>`<div><label>${n}</label><input name="${k}" type="number" min="${a}" max="${b}" value="${c.participation[k]}"></div>`).join('')}</div><button class="primary section">保存预算</button></form></section><section class="panel"><h2>独立工作环境</h2><div class="notice-line"><span>Python venv</span>${pill(state.environment.venvReady?'已创建':'未创建',!state.environment.venvReady)}</div><p class="path">${esc(state.environment.venv)}</p><div class="notice-line"><span>图片理解</span>${pill('原生图片输入')}</div><div class="notice-line"><span>语音 / 视频解码</span>${pill(state.environment.audioVideoReady?'已安装 · 最多 60 秒':'等待安装',!state.environment.audioVideoReady)}</div><form id="media-form">${[["images","读取图片"],["audio","语音转写"],["video","视频抽帧与转写"],["forwards","展开聊天记录（合并转发）"],["links","读取 B站 / YouTube 链接（经 Wander）"]].map(([k,n])=>`<label class="check"><input type="checkbox" name="${k}" ${c.media[k]??true?"checked":""}>${n}</label>`).join("")}<p class="muted">聊天记录展开后，前 20 条左右作为文字给观察员和回复模型看。命中下面的不适内容词的聊天记录不会给任何模型看，直接用这句话回应（同一个群 10 分钟最多一次；留空就只跳过不回应）。</p><div class="fields"><div><label>不适内容的固定回应</label><input name="nsfwReply" maxlength="40" value="${esc(c.media.nsfwReply??"不爱看这种")}"></div><div><label>额外的不适内容词（每行一个；内置词表已覆盖常见的）</label><textarea name="nsfwWords" rows="2">${esc((c.media.nsfwWords||[]).join("\n"))}</textarea></div></div><button class="primary section">保存媒体设置</button></form><div class="hint">venv 隔离依赖。第一版不开放任意代码执行；媒体访问通过固定接口和路径检查。</div><div class="notice-line"><span>subagent / subsession 扩展功能</span>${pill('已加入后续计划')}</div><div class="notice-line"><span>ComfyUI</span>${pill('已加入后续计划')}</div></section>`;}
function stickers(){return head('表情包管理','同一张图片只让模型看一次；改过的解读以后直接使用。把群友常用的表情包加入机器人的表情库，并写下什么时候用。','<button data-media-reload>重新读取</button>')+stickerPage(media,mediaUi,{esc,time,pill,empty});}
async function loadMedia(){if(mediaLoading)return;mediaLoading=true;try{media=await api('media');}catch(e){media={error:e.message};}finally{mediaLoading=false;}if(tab==='stickers'&&state)render();}
