async function save(mutator){const c=structuredClone(state.config);mutator(c);await api('config','PUT',c);toast('已保存；旧任务与待发送回复已取消');await refresh();}
function form(id,fn){const f=$('#'+id);if(f)f.onsubmit=e=>{e.preventDefault();if(!leave(id))return;run(()=>fn(Object.fromEntries(new FormData(f)),f),e.submitter||f.querySelector('button:not([type=button])'));};}
// Disables the triggering button while the request runs, so double clicks cannot repeat an action.
async function run(fn,el){if(el?.disabled)return;if(el){el.disabled=true;el.classList.add('busy');}try{await fn();}catch(e){toast(e.message,'error');}finally{if(el){el.disabled=false;el.classList.remove('busy');}}}
