  if(a==='whoami'){const r=await api('onebot/whoami','POST',{}),input=$('#bot-id');if(!r.account)throw new Error('OneBot 没有返回登录账号');if(input.value.trim()!==r.account){input.value=r.account;dirty.add('identity-form');}toast(`OneBot 当前登录：QQ ${r.account}${r.nickname?`（${r.nickname}）`:''}，已填入机器人 QQ；保存后生效`);return;}
  if(a==='group-list'){const list=await api('onebot/groups','POST',{}),have=new Set([...document.querySelectorAll('[data-group-row] [name=gid]')].map(x=>x.value.trim()));$('#group-picker').innerHTML=list.length?`<div class="picker">${list.map(g=>`<div class="notice-line"><span class="who"><span class="name">${esc(g.name)}</span><small class="muted">${esc(g.id)}${g.members?` · ${g.members} 人`:''}</small></span>${have.has(g.id)?pill('已添加','soft'):`<button type="button" class="small" data-pick-group="${esc(g.id)}" data-name="${esc(g.name)}">添加</button>`}</div>`).join('')}</div>`:empty('机器人还没有加入任何群');
   document.querySelectorAll('[data-pick-group]').forEach(x=>x.onclick=()=>{addGroupRow({id:x.dataset.pickGroup,name:x.dataset.name,enabled:true,persona:'gpt'});x.replaceWith(Object.assign(document.createElement('span'),{className:'pill soft',textContent:'已添加'}));});return;}
