  if(a==='event-setup'){const p=await api('event-setup');$('#connection-result').innerHTML=`<label>OneBot HTTP 客户端推送地址</label><input readonly value="${esc(p.url)}"><label>签名 Secret（不是 OneBot HTTP API Token）</label><input readonly value="${esc(p.secret)}" type="password"><p class="muted">在 OneBot 端启用 HTTP 事件推送并配置 Secret；HTTP 查询也必须能核对同一机器人账号。</p>`;return;}
